const data = $input.first().json;
const segments = data.segments || [];
const MIN_DUR = parseFloat($('Set Variables').first().json.MIN_DURATION);
const MAX_DUR = parseFloat($('Set Variables').first().json.MAX_DURATION);

// Build sliding window segments (30-90s) from Whisper word-level timestamps
const clips = [];
let i = 0;
while (i < segments.length) {
  let start = segments[i].start;
  let end = start;
  let text = '';
  let j = i;
  while (j < segments.length && (segments[j].end - start) < MAX_DUR) {
    end = segments[j].end;
    text += ' ' + segments[j].text;
    j++;
  }
  const duration = end - start;
  if (duration >= MIN_DUR) {
    clips.push({ start, end, duration: Math.round(duration), text: text.trim() });
  }
  i += Math.max(1, Math.floor((j - i) / 2)); // 50% overlap
}

return clips.map(c => ({ json: c }));

