const inputItem = $input.first().json;
const segItem = $('Loop Segments').first().json;

let scores;
try {
  const raw = inputItem.content[0].text;
  const clean = raw.replace(/```json?/g, '').replace(/```/g, '').trim();
  scores = JSON.parse(clean);
} catch(e) {
  scores = { hook_strength:0, emotional_intensity:0, information_density:0,
             standalone_value:0, cta_potential:0, controversy:0,
             relatability:0, quotability:0, suggested_title:'', hook_text:'', reason:'' };
}

const weights = {
  hook_strength: 0.20, emotional_intensity: 0.18, information_density: 0.12,
  standalone_value: 0.15, cta_potential: 0.10, controversy: 0.10,
  relatability: 0.10, quotability: 0.05
};

let composite = 0;
for (const [k, w] of Object.entries(weights)) {
  composite += (scores[k] || 0) * w;
}

return [{ json: {
  ...segItem,
  ...scores,
  composite_score: Math.round(composite * 10)
}}];

const items = $input.first().json.data || [];

// Sort by composite_score descending
const sorted = [...items].sort((a, b) => b.composite_score - a.composite_score);

// Diversity filter: no two clips within 30s of each other
const selected = [];
const MIN_GAP = 30;
for (const seg of sorted) {
  const overlaps = selected.some(s =>
    !(seg.end + MIN_GAP < s.start || seg.start > s.end + MIN_GAP)
  );
  if (!overlaps) selected.push(seg);
  if (selected.length >= 10) break;
}

return selected.map(s => ({ json: s }));

const TOP = parseInt($('Set Variables').first().json.TOP_CLIPS) || 7;
const items = $input.all();
return items.slice(0, TOP);

const raw = $input.first().json.stdout || '{}';
let crop;
try {
  const data = JSON.parse(raw);
  crop = data.dominant_crop;
} catch(e) {
  crop = { x: 0, y: 0, w: 608, h: 1080 };
}
return [{ json: { crop_data: crop } }];

