parameters.jsCode:
const CLIP_IDX = $runIndex + 1;
const OUTDIR = $('Set Variables').first().json.OUTPUT_DIR;
const seg = $('Loop Each Clip').first().json;

return [{ json: {
  clip_index: CLIP_IDX,
  start: seg.start,
  end: seg.end,
  composite_score: seg.composite_score,
  suggested_title: seg.suggested_title,
  hook_text: seg.hook_text,
  reason: seg.reason,
  final_file: `${OUTDIR}/final_clip_${CLIP_IDX}_score${seg.composite_score}.mp4`
}}];

// Check if music bed is available and clip is quiet
const MUSIC_PATH = $('Set Variables').first().json.MUSIC_PATH;
const hasMusicConfig = MUSIC_PATH && MUSIC_PATH.length > 0;
const stdout = $input.first().json.stdout || '';

let inputI = -70;
try {
  const match = stdout.match(/"input_i"\s*:\s*"([^"]+)"/);
  if (match) inputI = parseFloat(match[1]);
} catch(e) {}

// Add music bed only if configured and clip audio is quiet (voice-only)
const needsMusicBed = hasMusicConfig && inputI < -30;
return [{ json: { ...$('Record Clip Metadata').first().json, needsMusicBed, musicPath: MUSIC_PATH }}];

const items = $input.first().json.data || [];
const gallery = items.map(item => ({
  clip_index: item.clip_index,
  title: item.suggested_title,
  score: item.composite_score,
  start: item.start,
  end: item.end,
  hook: item.hook_text,
  reason: item.reason,
  file: item.final_file,
  thumbnail: item.final_file ? item.final_file.replace('.mp4', '_thumb.jpg') : null
}));

gallery.sort((a, b) => b.score - a.score);

return [{ json: { gallery, total_clips: gallery.length, generated_at: new Date().toISOString() }}];

// Receive selected clip IDs from webhook body
const body = $input.first().json.body || $input.first().json;
const selectedIds = body.clip_ids || [];
const gallery = $('Build Preview Gallery').first().json.gallery || [];

const finalClips = gallery.filter(c => selectedIds.includes(c.clip_index));

if (finalClips.length === 0) {
  // Default to top 3 if no selection received
  return gallery.slice(0, 3).map(c => ({ json: c }));
}
return finalClips.map(c => ({ json: c }));

const clips = $input.all().map(i => i.json);
const OUTDIR = $('Set Variables').first().json.OUTPUT_DIR;

// Write final manifest
const manifest = {
  status: 'ready',
  total_selected: clips.length,
  clips: clips,
  output_directory: OUTDIR,
  generated_at: new Date().toISOString()
};

return [{ json: manifest }];
